    import time

    LANGUAGE_WRAPPER = 'Consider the equation (x - {a})^{2{m}} - 1 = {n}. Let P be the product of the nonreal roots of this equation. Compute floor(P).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate m >= 3, a >= 2, and n >= 1 such that:
# - c = n+1 is positive and not a perfect m-th power
# - denominator a^2 - c^{1/m} is not near zero
# - the resulting P has a safe fractional margin from integers
# Retry up to a reasonable count
for _ in range(1000):
    m = rng.randint(3, 7)  # 3..6 for robust difficulty
    a = rng.randint(2, 9)
    n = rng.randint(200, 20000)
    c = n + 1
    # Avoid c == a^(2m) which would zero the numerator and risk degeneracy
    if a**(2*m) == c:
        continue
    # Compute t = c^(1/m) in float
    t = c ** (1.0 / m)
    denom = a**2 - t
    # Ensure denominator isn't vanishingly small
    if abs(denom) < 1e-6:
        continue
    # Ensure c is not a perfect m-th power via integer adjustment
    k = int(round(t))
    # Adjust k toward the true integer m-th root (if any)
    # This loop is safe as k is O(c^{1/m}) and m <= 6
    while k**m < c:
        k += 1
        if k > int(t) + 5:
            break
    while k**m > c and k > 0:
        k -= 1
    if k > 0 and k**m == c:
        continue
    P = (a**(2*m) - c) / denom
    if P <= 0:
        continue
    frac = abs(P - int(P))
    # Keep a margin from integer boundaries to avoid rounding issues
    if frac < 1e-4 or (1 - frac) < 1e-4:
        continue
    if P > 1e12:
        continue
    return {'a': a, 'm': m, 'n': n}
# Fallback safe instance
a, m, n = 3, 3, 12345
return {'a': a, 'm': m, 'n': n}

    def verifier(assign):
# Validate types and constraints, compute the answer, and return (True, answer)
# If invalid, return (False, None)
if not isinstance(assign, dict):
    return (False, None)
a = assign.get('a')
m = assign.get('m')
n = assign.get('n')
if not (isinstance(a, int) and isinstance(m, int) and isinstance(n, int)):
    # Missing or wrong types
    return (False, None)
if m < 3 or a < 2 or n < 1:
    # Enforce difficulty and positivity
    return (False, None)
c = n + 1
# Compute t = c^(1/m)
t = c ** (1.0 / m)
# Check c is not a perfect m-th power using integer correction
k = int(round(t))
while k**m < c:
    k += 1
    if k > int(t) + 5:
        break
while k**m > c and k > 0:
    k -= 1
if k**m == c:
    # We forbid perfect m-th powers to avoid trivialities and numeric edge cases
    return (False, None)
denom = a**2 - t
if abs(denom) < 1e-10:
    # Denominator too small; problem ill-conditioned
    return (False, None)
# Compute P using two equivalent forms to cross-check numeric stability
P1 = (a**(2*m) - c) / denom
# Alternative via the identity (X^m - Y^m)/(X - Y) = sum_{k=0}^{m-1} X^{m-1-k} Y^k, with X=a^2, Y=t
P2 = 0.0
tpower = 1.0
for k_idx in range(0, m):
    exp = 2 * (m - 1 - k_idx)
    P2 += (a ** exp) * tpower
    tpower *= t
# Cross-check within tight tolerance
if abs(P1 - P2) > 1e-6 * max(1.0, abs(P1)):
    return (False, None)
if P1 <= 0:
    return (False, None)
frac = abs(P1 - int(P1))
if frac < 1e-6 or (1 - frac) < 1e-6:
    # Too close to integer; potential float ambiguity
    return (False, None)
answer = int(P1)  # floor for positive P
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

